def find_regions_8conn(rows, cols, grid):
    """Find connected regions with 8-connectivity"""
    visited = [[False] * cols for _ in range(rows)]
    regions = {}

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                region = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if visited[cr][cc]:
                        continue
                    visited[cr][cc] = True
                    region.append((cr, cc))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if not visited[nr][nc] and grid[cr][cc] in [1, 8]:
                                    stack.append((nr, nc))
                regions[r] = region
    return regions

